/* Proprietà intellettuale di Francesco Antonio Binetti */
const fs = require('fs');

const base = fs.readFileSync('su03-08-tabelle-pivot.html', 'utf8');
const head = base.slice(0, base.indexOf('<body'));

const source = (href, label) => `<div class="source-footer" data-source-footer="true" style="position:absolute;left:220px;bottom:14px;z-index:4;"><a href="${href}" target="_blank" rel="noopener noreferrer" style="font-family:var(--font-mono);font-size:16px;color:var(--teal);text-decoration:underline;text-underline-offset:3px;">Fonte: ${label} ↗</a></div>`;
const author = '<div class="deck-author">Francesco Antonio Binetti</div>';
const page = '<div class="page-num"></div>';
const card = (tone, icon, title, text) => `<div class="card ${tone}"><span class="ic">${icon}</span><h3>${title}</h3><p>${text}</p></div>`;

function agenda(items) {
  return `<section class="slide no-top-label"><h2 class="h-sec">Cosa vedremo</h2><div class="agenda-list" style="grid-template-rows:repeat(${Math.ceil(items.length / 2)},auto);">${items.map((x, i) => `<div class="agenda-item"><span class="n">${String(i + 1).padStart(2, '0')}</span><span class="t">${x}</span></div>`).join('')}</div>${page}</section>`;
}

function frame(title, slides) {
  return head.replace(/<title>[\s\S]*?<\/title>/, `<title>${title}</title>`) + `<body class="course-su"><div class="deck-viewport"><div class="deck-stage" id="deckStage">${slides.join('\n')}</div></div><div class="progress" id="progress"></div><a class="home-btn" href="00-indice.html" title="Torna all'indice (I)">↩ Indice</a><script src="deck.js"></script></body></html>`;
}

const pivotSlides = [
  `<section class="slide title-slide active visible"><div class="title-left"><h1 class="h-mega reveal">Pivot<br><em class="hot">avanzate</em></h1><p class="lead reveal d1" style="margin-top:30px;">Dai primi riepiloghi a percentuali, raggruppamenti, campi calcolati, segmentazioni e grafici pivot controllabili.</p></div><div class="title-right"><div class="reveal" style="font-size:190px;z-index:2;">🧭</div></div>${author}</section>`,
  agenda(['Progettare la domanda', 'Mostrare percentuali', 'Confrontare periodi', 'Raggruppare date e numeri', 'Campi calcolati', 'Dettaglio e tracciabilità', 'Segmentazioni e timeline', 'Grafici pivot', 'Più pivot, una sorgente', 'Controlli di qualità', 'Laboratorio finale']),
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">La domanda viene prima dei campi</h2><p class="lead reveal d1">Una pivot avanzata non nasce trascinando campi a caso. Definisci prima indicatore, dimensioni, periodo e confronto.</p><div class="analogy reveal d2"><span class="big">Regola:</span> misura + categoria + tempo + filtro.</div></div><div class="pivot-box reveal d1"><div class="pivot-field"><span>Misura</span><b>Incasso</b></div><div class="pivot-field"><span>Categoria</span><b>Servizio</b></div><div class="pivot-field"><span>Tempo</span><b>Mese</b></div><div class="pivot-field"><span>Filtro</span><b>Sede</b></div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Lo stesso valore può raccontare storie diverse</h2><div class="grid4 reveal d1" style="margin-top:28px;">${card('teal','Σ','Somma','Quanto vale il totale della categoria.')} ${card('sky','#','Conteggio','Quanti record contribuiscono al risultato.')} ${card('gold','%','% del totale','Quanto pesa ogni categoria sull’insieme.')} ${card('red','Δ','Differenza','Quanto cambia rispetto a un riferimento.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">💡 Controllo</div><p>Aggiungi due volte lo stesso campo nei Valori: una copia come totale, l’altra come percentuale. Il confronto evita letture ingannevoli.</p></div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Percentuale di riga, colonna o totale?</h2><p class="lead reveal d1">Il denominatore cambia il significato. Scrivilo nel titolo del report e non lasciare che il lettore debba indovinarlo.</p><table class="table reveal d2" style="margin-top:28px;"><tr><th>Calcolo</th><th>Domanda</th><th>Esempio</th></tr><tr><td>% totale generale</td><td>Quanto pesa sul complesso?</td><td>Colore = 42% degli incassi</td></tr><tr><td>% totale riga</td><td>Come si divide questa categoria?</td><td>Servizio per sede</td></tr><tr><td>% totale colonna</td><td>Come si compone questo periodo?</td><td>Servizi dentro marzo</td></tr></table>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Confrontare periodi senza formule esterne</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','↔','Differenza da','Valore corrente meno periodo precedente.')} ${card('sky','%','% differenza da','Variazione relativa rispetto al riferimento.')} ${card('gold','∑','Totale progressivo','Accumula mese dopo mese per leggere l’andamento.')}</div><div class="analogy reveal d2" style="margin-top:24px;"><span class="big">In pratica:</span> mostra valore assoluto e variazione insieme: +20 euro e +40% non raccontano la stessa scala.</div>${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Raggruppare date e fasce</h2><p class="lead reveal d1">Centinaia di date diventano mesi, trimestri o anni; valori continui diventano fasce leggibili.</p><div class="note reveal d2"><div class="lbl">⚠️ Attenzione</div><p>Date vuote, testi che sembrano date e valori misti possono impedire il raggruppamento.</p></div></div><div class="grid2 reveal d1">${card('teal','📅','Tempo','Giorno → mese → trimestre → anno.')} ${card('gold','▥','Intervalli','Età 18–24, 25–34; importi 0–49, 50–99.')}</div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Campi calcolati: una misura derivata</h2><p class="lead reveal d1">Un campo calcolato usa i campi della sorgente per produrre un nuovo indicatore, per esempio margine o commissione.</p><div class="split" style="height:auto;margin-top:24px;"><div class="code">Margine = Ricavo - Costo<br><br>Commissione = Vendite * 0,05</div><div class="stack"><div class="card teal"><h3>Quando usarlo</h3><p>La logica è semplice, stabile e appartiene al report.</p></div><div class="card red"><h3>Quando evitarlo</h3><p>Se servono condizioni complesse, prepara la colonna nella sorgente o nel modello dati.</p></div></div></div>${source('https://support.microsoft.com/en-us/excel/calculate-values-in-a-pivottable','Calcoli nelle tabelle pivot — Microsoft')}${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Dal totale alle righe che lo compongono</h2><p class="lead reveal d1">Il drill-down permette di controllare un numero: apri il dettaglio della cella e confronta le righe sorgente.</p><div class="grid3 reveal d2" style="margin-top:28px;">${card('teal','1','Individua','Scegli il totale anomalo.')} ${card('sky','2','Apri il dettaglio','Visualizza i record che contribuiscono.')} ${card('gold','3','Verifica','Controlla duplicati, date, categorie e importi.')}</div><div class="analogy reveal d3" style="margin-top:24px;"><span class="big">Regola:</span> una cifra affidabile deve essere tracciabile fino ai dati sorgente.</div>${source('https://support.google.com/docs/answer/1272900','Creare e usare tabelle pivot — Google Sheets')}${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Segmentazioni e timeline rendono il report esplorabile</h2><div class="stack reveal d1" style="margin-top:24px;"><div class="agenda-item" style="border-color:var(--red);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">▣</span><div><b style="font-size:27px;">Slicer</b><br><span style="font-size:23px;color:var(--ink-faint);">Pulsanti visuali per categoria, sede o responsabile.</span></div></div><div class="agenda-item" style="border-color:var(--sky);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">↔</span><div><b style="font-size:27px;">Timeline</b><br><span style="font-size:23px;color:var(--ink-faint);">Filtro temporale dedicato in Excel.</span></div></div><div class="agenda-item" style="border-color:var(--gold);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">🔗</span><div><b style="font-size:27px;">Connessioni</b><br><span style="font-size:23px;color:var(--ink-faint);">Un controllo può pilotare più pivot che condividono la stessa sorgente.</span></div></div></div><div class="note reveal d2" style="margin-top:18px;"><div class="lbl">💡 Progettazione</div><p>Limita i controlli a quelli che cambiano davvero una decisione.</p></div>${source('https://support.google.com/docs/answer/9245556','Filtrare grafici e pivot con slicer — Google')}${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Il grafico pivot resta collegato al report</h2><p class="lead reveal d1">Filtri, raggruppamenti e aggiornamenti della pivot si riflettono nel grafico associato.</p><div class="analogy reveal d2"><span class="big">In pratica:</span> pivot per controllare i numeri, grafico per comunicare il pattern.</div></div><div class="illu reveal d1"><svg viewBox="0 0 620 410" width="620" height="410"><line x1="70" y1="340" x2="570" y2="340" stroke="#1c1714" stroke-width="7"/><rect x="110" y="210" width="76" height="130" fill="#3f7e8c"/><rect x="220" y="145" width="76" height="195" fill="#e6c14a"/><rect x="330" y="90" width="76" height="250" fill="#e6533b"/><rect x="440" y="170" width="76" height="170" fill="#163b35"/></svg><div class="illu-cap">Il filtro cambia tabella e grafico insieme</div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Più pivot, una sola sorgente pulita</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','🗃','Sorgente unica','Evita copie divergenti della stessa tabella.')} ${card('sky','🔄','Aggiornamento','Definisci chi aggiorna, quando e da quale intervallo.')} ${card('gold','🧠','Cache e modello','In Excel pivot collegate possono condividere cache e comportamento.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">⚠️ Effetto collegato</div><p>In Excel, copie della stessa pivot possono condividere cache: raggruppamenti e campi calcolati possono influenzarsi. Verifica prima di progettare report indipendenti.</p></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Controlli prima della consegna</h2><div class="grid4 reveal d1" style="margin-top:28px;">${card('teal','✓','Quadratura','Totale pivot uguale al totale sorgente.')} ${card('sky','✓','Aggiornamento','Nuove righe comprese nel range.')} ${card('gold','✓','Formato','Percentuali, valute e date coerenti.')} ${card('red','✓','Filtri','Filtri attivi visibili al lettore.')}</div><div class="analogy reveal d2" style="margin-top:24px;"><span class="big">Regola:</span> salva una vista senza filtri nascosti e con la data dell’ultimo aggiornamento.</div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Laboratorio: cruscotto vendite</h2><p class="lead reveal d1">Parti da Data, Sede, Servizio, Operatore, Ricavo e Costo.</p><div class="grid2 reveal d2" style="margin-top:24px;">${card('teal','A','Pivot 1','Ricavo e margine per servizio, con % del totale.')} ${card('sky','B','Pivot 2','Trend mensile e variazione dal mese precedente.')} ${card('gold','C','Controlli','Slicer per sede e operatore, periodo visibile.')} ${card('red','D','Verifica','Apri il dettaglio di un valore e quadrane il totale.')}</div>${page}</section>`,
  `<section class="slide closing"><div class="center" style="align-items:center;text-align:center;"><h2 class="h-big reveal">Una pivot avanzata<br>è un report <em class="gold">verificabile.</em></h2><p class="lead reveal d1" style="text-align:center;margin-top:24px;">Percentuali, confronti e filtri servono solo quando la domanda è chiara e il totale resta tracciabile.</p><div class="chips reveal d2" style="margin-top:28px;"><a class="chip" href="su03-10-grafici.html" style="background:var(--gold);color:var(--ink);">Prossimo → SU03.10 · Grafici</a><a class="chip" href="00-indice.html">Torna all’indice</a></div></div>${page}${author}</section>`
];

const chartSlides = [
  `<section class="slide title-slide active visible"><div class="title-left"><h1 class="h-mega reveal">Grafici<br><em class="hot">che parlano</em></h1><p class="lead reveal d1" style="margin-top:30px;">Scegliere il grafico giusto, preparare i dati e comunicare confronti, trend, composizioni e relazioni senza distorcere.</p></div><div class="title-right"><div class="reveal" style="font-size:190px;z-index:2;">📈</div></div>${author}</section>`,
  agenda(['Domanda prima del grafico', 'Preparare i dati', 'Barre e colonne', 'Linee e tempo', 'Composizione', 'Dispersione', 'Istogrammi', 'Elementi essenziali', 'Scale corrette', 'Colori e accessibilità', 'Grafici dinamici', 'Grafici combinati e assi', 'Grafici speciali e sparkline', 'Trend e previsione', 'Dashboard e revisione']),
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Il grafico è una risposta visuale</h2><p class="lead reveal d1">Prima di aprire Inserisci → Grafico, completa la frase: “Voglio far vedere che…”.</p><div class="analogy reveal d2"><span class="big">Regola:</span> una domanda, un messaggio principale, un grafico.</div></div><div class="grid2 reveal d1">${card('teal','↔','Confronto','Quale categoria è maggiore?')} ${card('sky','↗','Trend','Come cambia nel tempo?')} ${card('gold','◔','Composizione','Come si divide il totale?')} ${card('red','⠿','Relazione','Due variabili si muovono insieme?')}</div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Dati ordinati, grafico prevedibile</h2><div class="grid4 reveal d1" style="margin-top:28px;">${card('teal','▤','Intestazioni','Nomi brevi e univoci per categorie e serie.')} ${card('sky','123','Numeri veri','Valori numerici, non testo con simboli digitati.')} ${card('gold','📅','Date vere','Ordine temporale riconosciuto dal foglio.')} ${card('red','∅','Vuoti espliciti','Decidi se significano zero, dato mancante o non applicabile.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">💡 Selezione</div><p>Seleziona intestazioni e dati, ma escludi totali duplicati: una serie “Totale” spesso raddoppia visivamente ciò che è già rappresentato.</p></div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Barre per confrontare categorie</h2><p class="lead reveal d1">La lunghezza è facile da confrontare. Le barre orizzontali funzionano bene con etichette lunghe; le colonne con poche categorie compatte.</p><div class="split" style="height:auto;margin-top:22px;"><div class="illu reveal d2"><svg viewBox="0 0 650 360" width="650" height="360"><rect x="90" y="45" width="430" height="48" fill="#163b35"/><rect x="90" y="125" width="330" height="48" fill="#3f7e8c"/><rect x="90" y="205" width="235" height="48" fill="#e6c14a"/><rect x="90" y="285" width="150" height="48" fill="#e6533b"/></svg><div class="illu-cap">Ordina le categorie per rendere immediato il confronto</div></div><div class="stack"><div class="card teal"><h3>Buona scelta</h3><p>Ricavi per servizio, tempi per attività, voti per criterio.</p></div><div class="card red"><h3>Evita</h3><p>3D, prospettiva e assi troncati che alterano le lunghezze.</p></div></div></div>${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Linee per leggere il tempo</h2><p class="lead reveal d1">La linea mette in evidenza direzione, picchi, stagionalità e cambi di ritmo su intervalli ordinati.</p><div class="note reveal d2"><div class="lbl">⚠️ Attenzione</div><p>Collegare categorie senza ordine suggerisce una continuità che non esiste.</p></div></div><div class="illu reveal d1"><svg viewBox="0 0 650 410" width="650" height="410"><polyline points="55,320 160,270 265,292 370,180 475,210 580,90" fill="none" stroke="#e6533b" stroke-width="14"/><g fill="#163b35">${[[55,320],[160,270],[265,292],[370,180],[475,210],[580,90]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="12"/>`).join('')}</g><line x1="45" y1="350" x2="610" y2="350" stroke="#1c1714" stroke-width="6"/></svg><div class="illu-cap">Mesi in ordine, intervalli coerenti, poche serie</div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Composizione: parti di un totale</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','▥','Barre impilate','Confrontano totale e composizione tra più categorie.')} ${card('sky','100%','100% impilate','Confrontano proporzioni, non quantità assolute.')} ${card('gold','◔','Torta o anello','Solo poche parti, tutte positive, che sommano davvero al 100%.')}</div><div class="analogy reveal d2" style="margin-top:24px;"><span class="big">Regola:</span> se devi confrontare angoli sottili, usa barre: l’occhio confronta meglio le lunghezze.</div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Dispersione: cercare relazioni</h2><p class="lead reveal d1">Ogni punto rappresenta due misure: una sull’asse X e una sull’asse Y. Serve per correlazioni, gruppi e valori anomali.</p><div class="split" style="height:auto;margin-top:22px;"><div class="illu reveal d2"><svg viewBox="0 0 620 390" width="620" height="390"><line x1="70" y1="330" x2="570" y2="330" stroke="#1c1714" stroke-width="6"/><line x1="70" y1="330" x2="70" y2="40" stroke="#1c1714" stroke-width="6"/>${[[120,290],[170,260],[225,275],[280,205],[335,225],[390,160],[450,130],[520,75]].map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${10+i%3*3}" fill="${i===6?'#e6533b':'#3f7e8c'}"/>`).join('')}</svg><div class="illu-cap">Prezzo sull’asse X, quantità sull’asse Y</div></div><div class="stack"><div class="card teal"><h3>Correlazione ≠ causa</h3><p>Due variabili possono muoversi insieme senza che una provochi l’altra.</p></div><div class="card red"><h3>Outlier</h3><p>Un punto isolato va verificato: può essere un caso importante o un errore.</p></div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Istogramma: vedere una distribuzione</h2><p class="lead reveal d1">Raggruppa valori numerici in intervalli e conta quante osservazioni cadono in ogni fascia.</p><div class="grid3 reveal d2" style="margin-top:26px;">${card('teal','▥','Domanda','Dove si concentra la maggior parte dei valori?')} ${card('sky','↔','Ampiezza classi','Fasce troppo larghe nascondono; troppo strette creano rumore.')} ${card('gold','⌁','Forma','Cerca simmetria, code, più picchi e valori estremi.')}</div><div class="note reveal d3" style="margin-top:22px;"><div class="lbl">💡 Distinzione</div><p>Le colonne di un istogramma si toccano perché rappresentano intervalli continui; quelle di un grafico a colonne rappresentano categorie separate.</p></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Titolo, assi, legenda, etichette</h2><div class="grid4 reveal d1" style="margin-top:28px;">${card('teal','T','Titolo-messaggio','“I ricavi crescono da gennaio”, non “Grafico ricavi”.')} ${card('sky','X/Y','Assi','Nome, unità e scala leggibili.')} ${card('gold','≡','Legenda','Serve solo con più serie; meglio etichette dirette quando possibile.')} ${card('red','123','Etichette dati','Usale sui valori importanti, non su ogni punto per abitudine.')}</div>${source('https://support.microsoft.com/en-us/excel/get-started/create-a-chart-from-start-to-finish','Creare un grafico — Microsoft Excel')}${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">La scala può cambiare la storia</h2><div class="grid2 reveal d1" style="margin-top:28px;">${card('teal','0','Barre da zero','Troncare l’asse amplifica differenze piccole nella lunghezza.')} ${card('sky','↕','Linee contestuali','Un asse non zero può essere utile, ma va reso evidente.')} ${card('gold','⇄','Intervalli regolari','Passi diseguali fanno sembrare costante ciò che non lo è.')} ${card('red','3D','Niente prospettiva','Profondità e inclinazione ostacolano confronti accurati.')}</div><div class="analogy reveal d2" style="margin-top:24px;"><span class="big">Correttezza:</span> il grafico deve conservare le proporzioni che il dato possiede.</div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Colore come informazione, non decorazione</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','●','Base neutra','Una tinta coerente per ciò che non richiede attenzione.')} ${card('gold','●','Accento','Un solo colore forte per evidenziare il punto del messaggio.')} ${card('red','Aa','Accessibilità','Contrasto sufficiente e significato non affidato solo al colore.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">💡 Controllo</div><p>Stampa mentalmente in scala di grigi: serie ed evidenze restano distinguibili grazie a etichette, forme o pattern?</p></div>${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Grafici dinamici e PivotChart</h2><p class="lead reveal d1">Intervalli strutturati, pivot e slicer permettono al grafico di aggiornarsi e filtrarsi senza ricostruirlo.</p><div class="analogy reveal d2"><span class="big">In pratica:</span> sorgente unica → pivot controllata → grafico leggibile.</div></div><div class="stack reveal d1"><div class="agenda-item" style="border-color:var(--red);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">🔄</span><div><b style="font-size:27px;">Aggiorna</b><br><span style="font-size:23px;color:var(--ink-faint);">Nuove righe incluse nella sorgente.</span></div></div><div class="agenda-item" style="border-color:var(--sky);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">▣</span><div><b style="font-size:27px;">Filtra</b><br><span style="font-size:23px;color:var(--ink-faint);">Slicer coerenti con la domanda.</span></div></div><div class="agenda-item" style="border-color:var(--gold);padding:12px 4px;"><span style="font-size:34px;min-width:50px;">✓</span><div><b style="font-size:27px;">Controlla</b><br><span style="font-size:23px;color:var(--ink-faint);">Titolo e scala dopo ogni filtro.</span></div></div></div></div>${source('https://support.microsoft.com/en-US/Excel/overview-of-pivottables-and-pivotcharts','PivotTable e PivotChart — Microsoft')}${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Laboratorio: quattro domande, quattro grafici</h2><div class="grid2 reveal d1" style="margin-top:24px;">${card('teal','A','Confronto','Ricavi per servizio → barre ordinate.')} ${card('sky','B','Trend','Incasso mensile → linea.')} ${card('gold','C','Composizione','Quota per sede → barre 100% impilate.')} ${card('red','D','Relazione','Prezzo e quantità → dispersione.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">Consegna</div><p>Per ogni grafico scrivi il messaggio nel titolo, giustifica il tipo scelto e indica una scelta che potrebbe distorcere la lettura.</p></div>${page}</section>`,
  `<section class="slide closing"><div class="center" style="align-items:center;text-align:center;"><h2 class="h-big reveal">Il grafico giusto<br>rende il dato <em class="gold">onesto.</em></h2><p class="lead reveal d1" style="text-align:center;margin-top:24px;">Tipo, scala, ordine e colore devono aiutare il lettore a vedere la relazione reale, non a impressionarlo.</p><div class="chips reveal d2" style="margin-top:28px;"><a class="chip" href="su03-11-fogli-calcolo-avanzati.html" style="background:var(--gold);color:var(--ink);">Prossimo → SU03.11 · Fogli avanzati</a><a class="chip" href="00-indice.html">Torna all’indice</a></div></div>${page}${author}</section>`
];

const chartExpansion = [
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Righe, colonne e serie: chi rappresenta cosa?</h2><p class="lead reveal d1">Il foglio interpreta una dimensione come categorie e le altre come serie. Se il risultato sembra “girato”, controlla l’orientamento prima di cambiare grafico.</p><div class="analogy reveal d2"><span class="big">Regola:</span> una riga per osservazione, una colonna per variabile.</div></div><table class="table reveal d1"><tr><th>Mese</th><th>Ricavi</th><th>Costi</th></tr><tr><td>Gen</td><td>8.200</td><td>5.100</td></tr><tr><td>Feb</td><td>9.400</td><td>5.600</td></tr><tr><td>Mar</td><td>10.100</td><td>6.000</td></tr></table></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Grafico combinato: quantità e tasso insieme</h2><p class="lead reveal d1">Colonne e linea possono convivere quando rappresentano misure diverse ma legate dalla stessa sequenza temporale.</p><div class="grid3 reveal d2" style="margin-top:26px;">${card('teal','▥','Colonne','Ricavi mensili in euro.')} ${card('sky','↗','Linea','Margine percentuale mese per mese.')} ${card('gold','✓','Legame','Stesso periodo, messaggi complementari.')}</div><div class="note reveal d3" style="margin-top:22px;"><div class="lbl">⚠️ Limite</div><p>Non combinare tipi soltanto per rendere il grafico più movimentato: ogni codifica deve avere un motivo leggibile.</p></div>${source('https://support.google.com/docs/answer/190718','Tipi di grafico — Google Sheets')}${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Secondo asse: utile, ma facile da manipolare</h2><div class="grid2 reveal d1" style="margin-top:28px;">${card('teal','✓','Quando aiuta','Serie con unità e ordini di grandezza diversi, come euro e percentuale.')} ${card('sky','Aa','Come dichiararlo','Titoli su entrambi gli assi e colori coerenti con le serie.')} ${card('gold','↕','Rischio','Due scale scelte male possono far sembrare correlate serie indipendenti.')} ${card('red','1','Alternativa','Due grafici allineati spesso sono più trasparenti di due assi.')}</div>${source('https://support.microsoft.com/en-US/Office/excelexp/add-or-remove-a-secondary-axis-in-a-chart-in-excel','Asse secondario — Microsoft Excel')}${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Grafico ad area: il volume nel tempo</h2><p class="lead reveal d1">L’area enfatizza quantità accumulate e contributo al totale. Funziona meglio con poche serie e ordine stabile.</p><div class="note reveal d2"><div class="lbl">⚠️ Sovrapposizione</div><p>In un’area non impilata, una serie può nasconderne un’altra. Se interessa solo il trend, preferisci la linea.</p></div></div><div class="illu reveal d1"><svg viewBox="0 0 620 400" width="620" height="400"><path d="M50 340 L50 260 L150 230 L250 270 L350 160 L450 190 L570 90 L570 340 Z" fill="#3f7e8c" opacity=".75"/><path d="M50 340 L50 300 L150 280 L250 240 L350 225 L450 145 L570 165 L570 340 Z" fill="#e6c14a" opacity=".72"/><line x1="45" y1="340" x2="580" y2="340" stroke="#1c1714" stroke-width="6"/></svg><div class="illu-cap">L’area porta l’attenzione sulla quantità, non solo sulla direzione</div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Cascata: spiegare come cambia un totale</h2><p class="lead reveal d1">Il waterfall parte da un valore iniziale e mostra contributi positivi e negativi fino al risultato finale.</p><div class="grid4 reveal d2" style="margin-top:26px;">${card('teal','①','Partenza','Fatturato lordo.')} ${card('sky','＋','Aumenti','Nuovi clienti e servizi.')} ${card('red','−','Riduzioni','Costi, sconti e rimborsi.')} ${card('gold','＝','Arrivo','Margine netto.')}</div><div class="analogy reveal d3" style="margin-top:24px;"><span class="big">In pratica:</span> mostra il ponte tra due totali, non una semplice classifica.</div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Radar: profili multidimensionali con cautela</h2><p class="lead reveal d1">Un radar confronta più criteri sulla stessa scala. È suggestivo, ma aree e angoli sono difficili da confrontare con precisione.</p><div class="grid3 reveal d2" style="margin-top:26px;">${card('teal','5','Pochi criteri','Mantieni 4–7 assi con significato chiaro.')} ${card('sky','↔','Stessa scala','Tutti i criteri devono avere intervalli confrontabili.')} ${card('red','▥','Alternativa','Barre raggruppate o small multiples sono spesso più leggibili.')}</div><div class="note reveal d3" style="margin-top:22px;"><div class="lbl">💡 Uso sensato</div><p>Profilo sintetico di competenze o requisiti, accompagnato dai valori numerici.</p></div>${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Heatmap: il colore dentro una matrice</h2><p class="lead reveal d1">Una scala colore applicata a una tabella fa emergere zone alte, basse o anomale senza perdere righe e colonne.</p><div class="analogy reveal d2"><span class="big">Regola:</span> legenda visibile e scala coerente in tutta la matrice.</div></div><div class="illu reveal d1"><svg viewBox="0 0 520 420" width="520" height="420">${Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>`<rect x="${45+c*86}" y="${20+r*76}" width="78" height="68" rx="7" fill="${['#ece0cf','#e6c14a','#d98a2b','#e6533b','#3f7e8c'][(r*2+c)%5]}"/>`).join('')).join('')}</svg><div class="illu-cap">Giorni × fasce orarie: il pattern appare senza creare 25 barre</div></div></div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Sparkline: un andamento dentro la cella</h2><p class="lead reveal d1">Le sparkline sono mini-grafici senza assi completi, utili accanto a ogni riga di una tabella operativa.</p><div class="split" style="height:auto;margin-top:24px;"><div class="code">=SPARKLINE(B2:M2)<br><br>=SPARKLINE(B2:M2;<br>{"charttype","column"})</div><div class="stack">${card('teal','↗','Trend rapido','Mostra direzione e oscillazioni per cliente o prodotto.')} ${card('gold','↕','Scala comune','Per confrontare righe, usa minimo e massimo coerenti.')}</div></div>${source('https://support.google.com/docs/answer/3093289','Funzione SPARKLINE — Google Sheets')}${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Trendline: sintetizzare una relazione</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','／','Lineare','Riassume una tendenza approssimativamente rettilinea.')} ${card('sky','R²','Adattamento','R² descrive quanto il modello segue i dati, non prova causalità.')} ${card('red','⚠','Estrapolazione','Fuori dall’intervallo osservato l’incertezza cresce rapidamente.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">💡 Metodo</div><p>Osserva prima la dispersione dei punti; una linea elegante non corregge dati pochi, distorti o pieni di eccezioni.</p></div>${source('https://support.google.com/docs/answer/6075154','Aggiungere una linea di tendenza — Google Sheets')}${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Media mobile: ridurre il rumore</h2><p class="lead reveal d1">La media mobile sostituisce ogni punto con la media di una finestra vicina, rendendo più leggibile il trend di fondo.</p><div class="note reveal d2"><div class="lbl">⚠️ Compromesso</div><p>Una finestra ampia leviga di più, ma ritarda e nasconde cambiamenti improvvisi.</p></div></div><div class="illu reveal d1"><svg viewBox="0 0 650 410" width="650" height="410"><polyline points="50,290 120,170 190,260 260,120 330,230 400,110 470,190 540,80 610,150" fill="none" stroke="#d8c9b4" stroke-width="10"/><polyline points="50,250 120,230 190,210 260,190 330,175 400,155 470,140 540,120 610,105" fill="none" stroke="#e6533b" stroke-width="13"/></svg><div class="illu-cap">Grigio: valori; rosso: andamento smussato</div></div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Previsione: mostrare anche l’incertezza</h2><div class="grid3 reveal d1" style="margin-top:28px;">${card('teal','↗','Stima','Una proiezione dipende dal modello e dai dati storici.')} ${card('sky','≋','Intervallo','Una fascia comunica valori plausibili meglio di una sola linea.')} ${card('red','!','Assunzioni','Eventi nuovi, stagionalità e cambi di processo possono invalidarla.')}</div><div class="analogy reveal d2" style="margin-top:24px;"><span class="big">Correttezza:</span> separa chiaramente dati osservati e valori previsti.</div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Annotazioni: spiegare picchi e cambi di fase</h2><p class="lead reveal d1">Una nota breve collega un’anomalia a un evento noto senza costringere il lettore a cercare la spiegazione altrove.</p><div class="grid3 reveal d2" style="margin-top:26px;">${card('teal','●','Punto preciso','“15 marzo: lancio promozione”.')} ${card('sky','│','Linea evento','Segna un cambio di prezzo o procedura.')} ${card('gold','▧','Fascia','Evidenzia campagna, chiusura o periodo eccezionale.')}</div><div class="note reveal d3" style="margin-top:22px;"><div class="lbl">💡 Misura</div><p>Annota soltanto ciò che modifica l’interpretazione; troppe note trasformano il grafico in un documento.</p></div>${page}</section>`,
  `<section class="slide"><div class="split"><div class="stack"><h2 class="h-sec reveal">Small multiples: stessa scala, pannelli separati</h2><p class="lead reveal d1">Ripeti lo stesso grafico per sedi, prodotti o gruppi. La struttura identica rende confrontabili forme e differenze.</p><div class="analogy reveal d2"><span class="big">Regola:</span> stessi assi, stesso periodo, stesso ordine.</div></div><div class="grid2 reveal d1">${card('teal','A','Sede centro','Trend mensile isolato.')} ${card('sky','B','Sede nord','Stessa scala del centro.')} ${card('gold','C','Sede sud','Stesso intervallo temporale.')} ${card('red','D','Online','Stessa codifica visiva.')}</div></div>${page}</section>`,
  `<section class="slide tight"><h2 class="h-sec reveal">Dashboard: gerarchia prima della decorazione</h2><div class="grid4 reveal d1" style="margin-top:26px;">${card('teal','1','KPI','3–6 numeri decisivi, con periodo e confronto.')} ${card('sky','2','Trend','Uno o due grafici per il cambiamento nel tempo.')} ${card('gold','3','Cause','Confronti per categoria o segmento.')} ${card('red','4','Dettaglio','Tabella filtrabile per verificare i casi.')}</div><div class="note reveal d2" style="margin-top:22px;"><div class="lbl">⚠️ Coerenza</div><p>Filtri, unità e date devono valere per tutti i componenti; altrimenti il cruscotto confronta universi diversi.</p></div>${page}</section>`,
  `<section class="slide"><h2 class="h-sec reveal">Revisione finale: ricostruire un grafico debole</h2><p class="lead reveal d1">Prendi un grafico 3D con molte serie, legenda lontana e titolo generico. Ridisegnalo documentando ogni scelta.</p><div class="grid2 reveal d2" style="margin-top:24px;">${card('teal','A','Messaggio','Scrivi la frase che il lettore deve capire.')} ${card('sky','B','Tipo','Scegli la codifica adatta alla relazione.')} ${card('gold','C','Pulizia','Rimuovi 3D, bordi, colori e griglie inutili.')} ${card('red','D','Verifica','Controlla scala, unità, fonte e valori mancanti.')}</div><div class="analogy reveal d3" style="margin-top:22px;"><span class="big">Consegna:</span> prima/dopo + tre motivazioni verificabili.</div>${page}</section>`
];

chartSlides.splice(chartSlides.length - 1, 0, ...chartExpansion);

// The chart deck is designed as a reading-first handout: cards must explain
// not only what a chart is called, but what decision it supports and where the
// most common interpretation error hides. Keeping the expansion map separate
// makes the short layout definitions above readable while ensuring regenerated
// decks retain the full teaching copy.
const chartCopyExpansion = new Map([
  ['Quale categoria è maggiore?', 'Confronta categorie indipendenti e rende visibili differenze, graduatorie e distanze. Esempio: quale servizio genera più ricavi e di quanto supera il secondo?'],
  ['Come cambia nel tempo?', 'Mostra direzione, velocità del cambiamento, picchi e stagionalità. Richiede date ordinate e intervalli temporali coerenti.'],
  ['Come si divide il totale?', 'Descrive il peso delle parti rispetto a un insieme definito. Prima verifica che le componenti siano confrontabili e che il totale sia significativo.'],
  ['Due variabili si muovono insieme?', 'Cerca associazioni, gruppi e anomalie tra due misure numeriche. Una relazione visiva suggerisce domande, ma non dimostra una causa.'],
  ['Nomi brevi e univoci per categorie e serie.', 'Nomi brevi e univoci permettono al foglio di distinguere categorie e serie. Evita intestazioni vuote, duplicate o distribuite su più righe.'],
  ['Valori numerici, non testo con simboli digitati.', 'Valori numerici, non testo con simboli digitati: “€ 120” scritto a mano può essere ignorato o ordinato male. Applica il formato valuta al numero 120.'],
  ['Ordine temporale riconosciuto dal foglio.', 'Usa date reali, non nomi di mesi digitati senza anno. In questo modo ordinamento, raggruppamento e distanza temporale restano corretti.'],
  ['Decidi se significano zero, dato mancante o non applicabile.', 'Decidi se un vuoto significa zero, dato non raccolto o caso non applicabile. Le tre situazioni producono grafici e conclusioni differenti.'],
  ['Ricavi per servizio, tempi per attività, voti per criterio.', 'Ricavi per servizio, tempi per attività e voti per criterio. Ordina per valore quando la graduatoria conta; conserva l’ordine naturale quando esiste.'],
  ['3D, prospettiva e assi troncati che alterano le lunghezze.', 'Evita 3D, prospettiva, troppe categorie e assi troncati: rendono difficile confrontare le lunghezze. Se le etichette sono lunghe, passa alle barre orizzontali.'],
  ['La linea mette in evidenza direzione, picchi, stagionalità e cambi di ritmo su intervalli ordinati.', 'La linea mette in evidenza direzione, picchi, stagionalità e cambi di ritmo su intervalli ordinati. Mantieni la stessa frequenza di rilevazione e non collegare automaticamente periodi privi di dati. Con più serie, evidenzia quella principale e porta le altre in secondo piano.'],
  ['Collegare categorie senza ordine suggerisce una continuità che non esiste.', 'Collegare categorie senza ordine suggerisce una continuità che non esiste. Per confrontare prodotti, persone o sedi usa barre; la linea implica che abbia senso osservare il percorso tra un punto e il successivo.'],
  ['Confrontano totale e composizione tra più categorie.', 'Mostrano insieme quantità totale e contributo delle parti. Le parti interne, però, sono difficili da confrontare quando non condividono la stessa linea di base.'],
  ['Confrontano proporzioni, non quantità assolute.', 'Portano ogni barra al 100% e confrontano le proporzioni. Nascondono però la dimensione dei totali: affianca i valori assoluti quando sono importanti.'],
  ['Solo poche parti, tutte positive, che sommano davvero al 100%.', 'Usale solo con poche parti positive che sommano davvero al 100%. Ordina le fette e mostra percentuale o valore, evitando categorie quasi indistinguibili.'],
  ['Due variabili possono muoversi insieme senza che una provochi l’altra.', 'Due variabili possono muoversi insieme per coincidenza o per l’effetto di una terza variabile. Descrivi intensità e direzione senza trasformare la correlazione in causalità.'],
  ['Un punto isolato va verificato: può essere un caso importante o un errore.', 'Un punto isolato può rivelare un cliente speciale, un evento raro oppure un errore di registrazione. Verifica la riga sorgente prima di eliminarlo.'],
  ['Dove si concentra la maggior parte dei valori?', 'Individua fascia più frequente, dispersione e valori rari. Esempio: i tempi di consegna si concentrano tra 2 e 4 giorni oppure sono molto variabili?'],
  ['Fasce troppo larghe nascondono; troppo strette creano rumore.', 'Fasce troppo larghe nascondono gruppi e code; fasce troppo strette trasformano ogni oscillazione in rumore. Prova più ampiezze e dichiara gli intervalli.'],
  ['Cerca simmetria, code, più picchi e valori estremi.', 'Cerca simmetria, code lunghe, più picchi e valori estremi. Queste forme possono indicare gruppi diversi o un processo non uniforme.'],
  ['“I ricavi crescono da gennaio”, non “Grafico ricavi”.', 'Scrivi il messaggio principale, per esempio “I ricavi crescono da gennaio”, invece del generico “Grafico ricavi”. Il titolo deve restare vero anche dopo un filtro.'],
  ['Nome, unità e scala leggibili.', 'Indica nome, unità e scala: euro, percentuale, minuti o quantità. Un lettore non dovrebbe dedurre l’unità dal contesto o dalla forma dei numeri.'],
  ['Serve solo con più serie; meglio etichette dirette quando possibile.', 'Serve quando colori o simboli rappresentano più serie. Se lo spazio lo consente, etichetta direttamente le linee per ridurre il continuo salto tra legenda e dati.'],
  ['Usale sui valori importanti, non su ogni punto per abitudine.', 'Mostra valori finali, massimi, minimi o soglie utili. Etichettare ogni punto crea rumore e spesso duplica informazioni già leggibili sull’asse.'],
  ['Troncare l’asse amplifica differenze piccole nella lunghezza.', 'Nelle barre la lunghezza codifica il valore: partire sopra zero amplifica artificialmente differenze piccole. Se serve dettaglio, mostra anche i numeri o usa un’altra vista.'],
  ['Un asse non zero può essere utile, ma va reso evidente.', 'Per una linea un intervallo ristretto può mostrare variazioni operative importanti. Dichiara però minimo, massimo e contesto, così il lettore valuta l’ampiezza reale.'],
  ['Passi diseguali fanno sembrare costante ciò che non lo è.', 'Mantieni intervalli uguali tra tacche e date. Se mancano periodi, rendi visibile il vuoto invece di comprimere il tempo e suggerire continuità.'],
  ['Profondità e inclinazione ostacolano confronti accurati.', 'Profondità e inclinazione accorciano o nascondono le forme e non aggiungono informazione. Un grafico 2D è quasi sempre più preciso e leggibile.'],
  ['Una tinta coerente per ciò che non richiede attenzione.', 'Usa una tinta neutra e coerente per il contesto. Ripetere lo stesso colore per la stessa categoria aiuta il lettore a riconoscerla tra più grafici.'],
  ['Un solo colore forte per evidenziare il punto del messaggio.', 'Riserva un colore forte al dato che sostiene il messaggio: massimo, eccezione o serie principale. Se tutto è acceso, nulla emerge davvero.'],
  ['Contrasto sufficiente e significato non affidato solo al colore.', 'Garantisci contrasto tra testo, sfondo e segni. Affianca al colore etichette, simboli, pattern o spessori per chi distingue male alcune tonalità.'],
  ['Ricavi per servizio → barre ordinate.', 'Ricavi per servizio → barre ordinate. Inserisci unità in euro, periodo osservato e una nota se alcune categorie aggregano servizi differenti.'],
  ['Incasso mensile → linea.', 'Incasso mensile → linea. Mantieni tutti i mesi, segnala quelli incompleti e annota eventi che spiegano picchi o cadute.'],
  ['Quota per sede → barre 100% impilate.', 'Quota per sede → barre 100% impilate. Controlla che ogni barra rappresenti lo stesso universo e affianca il totale se le dimensioni cambiano molto.'],
  ['Prezzo e quantità → dispersione.', 'Prezzo e quantità → dispersione. Etichetta gli outlier, osserva eventuali gruppi e non presentare la relazione come prova di causalità.'],
  ['Ricavi mensili in euro.', 'Le colonne mostrano il volume mensile in euro e rendono confrontabili le quantità. Mantieni una base zero e un numero limitato di periodi.'],
  ['Margine percentuale mese per mese.', 'La linea mostra il margine percentuale sullo stesso calendario. Usa un colore distinto e dichiara chiaramente l’asse percentuale.'],
  ['Stesso periodo, messaggi complementari.', 'Le due serie devono condividere periodo e domanda: quanto vendiamo e con quale redditività. Se non esiste questo legame, separa i grafici.'],
  ['Intervalli strutturati, pivot e slicer permettono al grafico di aggiornarsi e filtrarsi senza ricostruirlo.', 'Intervalli strutturati, pivot e slicer permettono al grafico di aggiornarsi e filtrarsi senza ricostruirlo. Prima della consegna prova ad aggiungere una riga, cambiare filtro e rimuovere un valore: il grafico deve aggiornarsi senza perdere titolo, scala o ordine.'],
  ['Nuove righe incluse nella sorgente.', 'Usa una tabella strutturata o un intervallo dinamico, così le nuove righe entrano nel report. Mostra anche la data dell’ultimo aggiornamento.'],
  ['Slicer coerenti con la domanda.', 'Offri soltanto filtri che cambiano una decisione, come periodo, sede o categoria. Troppi slicer consumano spazio e nascondono lo stato corrente.'],
  ['Titolo e scala dopo ogni filtro.', 'Controlla che titolo, scala, ordine e percentuali restino corretti dopo ogni filtro. Un grafico dinamico può diventare vuoto o fuorviante in alcune combinazioni.'],
  ['Il foglio interpreta una dimensione come categorie e le altre come serie. Se il risultato sembra “girato”, controlla l’orientamento prima di cambiare grafico.', 'Il foglio interpreta una dimensione come categorie e le altre come serie. Se il risultato sembra “girato”, controlla l’orientamento prima di cambiare grafico. Le categorie descrivono ciò che compare sull’asse; ogni serie rappresenta invece una misura confrontata con le altre. Usa “Scambia righe/colonne” solo dopo aver identificato questi ruoli.'],
  ['Una riga per osservazione, una colonna per variabile.', 'Una riga per osservazione, una colonna per variabile e intestazioni sulla prima riga. Escludi subtotali e celle unite: diventerebbero serie artificiali o categorie vuote.'],
  ['L’area enfatizza quantità accumulate e contributo al totale. Funziona meglio con poche serie e ordine stabile.', 'L’area enfatizza quantità accumulate e contributo al totale. Funziona meglio con poche serie e ordine stabile. In una versione impilata, la serie inferiore conserva una base leggibile mentre quelle superiori mostrano soprattutto il contributo al totale. Se interessa confrontare ogni serie con precisione, usa linee o piccoli pannelli.'],
  ['In un’area non impilata, una serie può nasconderne un’altra. Se interessa solo il trend, preferisci la linea.', 'In un’area non impilata, una serie può nasconderne un’altra; trasparenze e ordine cambiano la percezione. Se interessa solo il trend, preferisci la linea. Se interessa la composizione, verifica che le parti siano additive e non si sovrappongano logicamente.'],
  ['Fatturato lordo.', 'È il valore iniziale verificabile da cui parte la riconciliazione. Indica periodo e unità per evitare confronti con basi differenti.'],
  ['Nuovi clienti e servizi.', 'Ogni aumento deve avere una categoria esplicita e non sovrapposta alle altre. Ordina i contributi secondo la storia che vuoi verificare.'],
  ['Costi, sconti e rimborsi.', 'Mostra separatamente costi, sconti e rimborsi: aggregarli in “altro” nasconde quali fattori riducono davvero il risultato.'],
  ['Margine netto.', 'Il valore finale deve coincidere con il totale calcolato nei dati. Se non quadra, il grafico sta nascondendo una voce o un errore.'],
  ['Mantieni 4–7 assi con significato chiaro.', 'Mantieni 4–7 criteri indipendenti e spiegati. Troppi assi producono una forma suggestiva ma impossibile da leggere con precisione.'],
  ['Tutti i criteri devono avere intervalli confrontabili.', 'Normalizza i criteri sulla stessa scala e chiarisci se un valore alto è sempre migliore. Mescolare euro, percentuali e giudizi grezzi deforma il profilo.'],
  ['Barre raggruppate o small multiples sono spesso più leggibili.', 'Se il confronto preciso conta, usa barre raggruppate o piccoli pannelli con scala comune. Il radar è più adatto a un profilo sintetico che a una graduatoria.'],
  ['Una scala colore applicata a una tabella fa emergere zone alte, basse o anomale senza perdere righe e colonne.', 'Una scala colore applicata a una tabella fa emergere zone alte, basse o anomale senza perdere righe e colonne. È utile per orari, calendari, correlazioni o prestazioni per sede. Prima scegli se il colore deve rappresentare intensità da minimo a massimo oppure distanza da un valore centrale.'],
  ['Legenda visibile e scala coerente in tutta la matrice.', 'Legenda visibile, valori mancanti distinti dallo zero e scala coerente in tutta la matrice. Se ogni riga usa un intervallo diverso, i colori non sono confrontabili.'],
  ['Mostra direzione e oscillazioni per cliente o prodotto.', 'Mostra rapidamente direzione e oscillazioni per ogni riga. Non sostituisce un grafico completo: mancano assi, valori e contesto temporale.'],
  ['Per confrontare righe, usa minimo e massimo coerenti.', 'Per confrontare righe, imposta minimo e massimo coerenti; altrimenti ogni sparkline usa una scala propria e variazioni diverse sembrano uguali.'],
  ['Riassume una tendenza approssimativamente rettilinea.', 'Riassume direzione e intensità media di una relazione approssimativamente rettilinea. Controlla sempre i punti: gruppi o curve possono rendere la retta fuorviante.'],
  ['R² descrive quanto il modello segue i dati, non prova causalità.', 'R² indica quanta variabilità viene descritta dal modello sui dati osservati. Non misura importanza, correttezza della causa o affidabilità fuori dal campione.'],
  ['Fuori dall’intervallo osservato l’incertezza cresce rapidamente.', 'Fuori dall’intervallo osservato l’incertezza cresce rapidamente e il processo può cambiare. Tratteggia la previsione e limita l’orizzonte.'],
  ['La media mobile sostituisce ogni punto con la media di una finestra vicina, rendendo più leggibile il trend di fondo.', 'La media mobile sostituisce ogni punto con la media di una finestra vicina, rendendo più leggibile il trend di fondo. Una finestra di tre mesi risponde a domande diverse da una di dodici: indica sempre ampiezza, posizione della finestra e gestione dei primi periodi. Mantieni visibili anche i dati originali per non nascondere anomalie.'],
  ['Una finestra ampia leviga di più, ma ritarda e nasconde cambiamenti improvvisi.', 'Una finestra ampia leviga di più, ma ritarda la risposta e può nascondere cambiamenti improvvisi. Confronta più finestre e scegline una coerente con il ciclo operativo, non quella che produce la curva più gradevole.'],
  ['Una proiezione dipende dal modello e dai dati storici.', 'Una proiezione dipende da qualità dei dati, modello e continuità del processo. Indica data di produzione e orizzonte della stima.'],
  ['Una fascia comunica valori plausibili meglio di una sola linea.', 'Una fascia comunica un insieme di valori plausibili e si allarga quando aumenta l’incertezza. Una singola linea suggerisce una precisione che non esiste.'],
  ['Eventi nuovi, stagionalità e cambi di processo possono invalidarla.', 'Documenta stagionalità, promozioni, chiusure e cambi di processo. Se le condizioni cambiano, aggiorna il modello invece di prolungare automaticamente il passato.'],
  ['“15 marzo: lancio promozione”.', 'Collega la nota al punto esatto e descrivi l’evento, non la forma già visibile. “15 marzo: lancio promozione” spiega il picco; “valore alto” no.'],
  ['Segna un cambio di prezzo o procedura.', 'Una linea verticale identifica un evento che influenza tutte le serie da quel momento: cambio prezzo, procedura, fornitore o metodo di rilevazione.'],
  ['Evidenzia campagna, chiusura o periodo eccezionale.', 'Una fascia evidenzia un intervallo con condizioni particolari, come campagna, chiusura o dati incompleti. Usa una tinta leggera per non coprire le serie.'],
  ['Trend mensile isolato.', 'Mostra il trend mensile della sede centro senza sovrapporlo alle altre. Il lettore può riconoscere forma, picchi e cambi di ritmo.'],
  ['Stessa scala del centro.', 'Usa esattamente scala, intervallo e ordine della sede centro. Solo così altezza e pendenza restano confrontabili tra pannelli.'],
  ['Stesso intervallo temporale.', 'Mantieni lo stesso intervallo temporale, includendo mesi senza dati. Tagliare periodi diversi produce confronti visivi falsi.'],
  ['Stessa codifica visiva.', 'Mantieni colori, spessori e posizione delle etichette. Cambia soltanto il gruppo rappresentato, non la grammatica del grafico.'],
  ['3–6 numeri decisivi, con periodo e confronto.', 'Mostra 3–6 indicatori decisivi, ciascuno con unità, periodo e confronto con obiettivo o periodo precedente. Un numero senza riferimento non comunica andamento.'],
  ['Uno o due grafici per il cambiamento nel tempo.', 'Usa uno o due grafici per il cambiamento nel tempo e annota eventi rilevanti. Evita di ripetere lo stesso trend in forme differenti.'],
  ['Confronti per categoria o segmento.', 'Spiega le cause con confronti per categoria, sede, prodotto o segmento. Collega ogni vista a una domanda operativa, non a semplice curiosità.'],
  ['Tabella filtrabile per verificare i casi.', 'Conserva una tabella filtrabile per risalire ai record e verificare anomalie. Il dashboard sintetizza, ma non deve impedire il controllo del dato.'],
  ['Scrivi la frase che il lettore deve capire.', 'Scrivi una frase verificabile che il lettore deve capire. Se emergono due messaggi indipendenti, separali in due grafici.'],
  ['Scegli la codifica adatta alla relazione.', 'Scegli la codifica in base alla relazione: barre per confronti, linea per tempo, dispersione per due misure, istogramma per distribuzioni.'],
  ['Rimuovi 3D, bordi, colori e griglie inutili.', 'Rimuovi 3D, bordi, colori e griglie che non aiutano la lettura. Mantieni invece unità, riferimento zero, fonte e annotazioni necessarie.'],
  ['Controlla scala, unità, fonte e valori mancanti.', 'Controlla scala, unità, fonte, filtri e valori mancanti. Confronta alcuni punti con la tabella sorgente prima di considerare concluso il lavoro.']
]);

for (let i = 0; i < chartSlides.length; i++) {
  for (const [brief, expanded] of chartCopyExpansion) {
    chartSlides[i] = chartSlides[i].replaceAll(brief, expanded);
  }
}

